helpers='''    private void loadBusinessSettings(){ taxBps=prefs.getBoolean("tax_enabled",false)?prefs.getInt("tax_bps",0):0; }\n    private String hashPin(String value){ try{ MessageDigest d=MessageDigest.getInstance("SHA-256"); byte[] b=d.digest(value.getBytes("UTF-8")); StringBuilder x=new StringBuilder(); for(byte z:b)x.append(String.format(Locale.US,"%02x",z&255)); return x.toString(); }catch(Exception e){throw new IllegalStateException(e);} }\n    private void requireOwner(Runnable action){\n        String stored=prefs.getString("owner_pin_hash","");\n        if(stored.isEmpty()){ setupOwnerPin(action); return; }\n        EditText pin=input("رقم المالك",false); pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);\n        new AlertDialog.Builder(this).setTitle("صلاحية المالك").setMessage("أدخل رقم المالك لإجراء هذا التعديل").setView(pin).setPositiveButton("متابعة",(d,w)->{ if(stored.equals(hashPin(pin.getText().toString().trim()))) action.run(); else error("رقم المالك غير صحيح"); }).setNegativeButton("إلغاء",null).show();\n    }\n    private void setupOwnerPin(Runnable after){\n        LinearLayout box=col(); box.setPadding(dp(14),dp(4),dp(14),0); EditText a=input("أنشئ رقم المالك",false),b=input("تأكيد رقم المالك",false); a.setInputType(2|16); b.setInputType(2|16); box.addView(a);box.addView(b);\n        AlertDialog dlg=new AlertDialog.Builder(this).setTitle("تهيئة رقم المالك").setMessage("لأمانك لا يتم تضمين رقم المالك داخل الكود العام. أدخله مرة واحدة على هذا الجهاز.").setView(box).setPositiveButton("حفظ",null).setNegativeButton("إلغاء",null).create();\n        dlg.setOnShowListener(v->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{ String p=a.getText().toString().trim(); if(p.length()<6){error("رقم المالك يجب أن يكون 6 أرقام على الأقل");return;} if(!p.equals(b.getText().toString().trim())){error("التأكيد غير مطابق");return;} prefs.edit().putString("owner_pin_hash",hashPin(p)).apply(); dlg.dismiss(); after.run(); })); dlg.show();\n    }\n\n'''
