# replace product grid with image background + overlay
def replace_between(text,start_marker,end_marker,new_text):
    a=text.index(start_marker); b=text.index(end_marker,a); return text[:a]+new_text+text[b:]

new_grid='''    private void renderProductsGrid(LinearLayout panel,String category){\n        while(panel.getChildCount()>2) panel.removeViewAt(2);\n        ScrollView scroll=new ScrollView(this); LinearLayout wrap=col(); List<PosDb.Product> ps=db.products(saleSearch,category);\n        for(int i=0;i<ps.size();i+=3){\n            LinearLayout r=row();\n            for(int j=i;j<Math.min(i+3,ps.size());j++){\n                PosDb.Product p=ps.get(j); FrameLayout card=new FrameLayout(this); card.setBackground(bg(PANEL2,Color.rgb(40,77,102),16));\n                boolean hasImage=p.imageUri!=null&&!p.imageUri.trim().isEmpty();\n                if(hasImage){ try{ ImageView im=new ImageView(this); im.setScaleType(ImageView.ScaleType.CENTER_CROP); im.setImageURI(Uri.parse(p.imageUri)); card.addView(im,new FrameLayout.LayoutParams(-1,-1)); }catch(Exception ignored){hasImage=false;} }\n                if(!hasImage){ TextView icon=txt(productIcon(p.category),44); icon.setGravity(Gravity.CENTER); card.addView(icon,new FrameLayout.LayoutParams(-1,-1)); }\n                LinearLayout overlay=col(); overlay.setPadding(dp(9),dp(5),dp(9),dp(6)); overlay.setBackgroundColor(Color.argb(205,5,16,25));\n                TextView name=txt(p.name,15); name.setTypeface(Typeface.DEFAULT_BOLD); name.setGravity(Gravity.CENTER); name.setTextColor(Color.WHITE);\n                TextView price=txt(money(p.priceMinor),15); price.setTypeface(Typeface.DEFAULT_BOLD); price.setGravity(Gravity.CENTER); price.setTextColor(ACCENT); overlay.addView(name); overlay.addView(price);\n                FrameLayout.LayoutParams op=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM); card.addView(overlay,op);\n                card.setOnClickListener(v->{ PosDb.CartLine line=cart.get(p.id); if(line==null){line=new PosDb.CartLine(p.id,1);cart.put(p.id,line);} else line.qty++; showPage(); });\n                LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(165),1); cp.setMargins(dp(5),dp(5),dp(5),dp(5)); r.addView(card,cp);\n            } wrap.addView(r,new LinearLayout.LayoutParams(-1,-2));\n        }\n        scroll.addView(wrap); panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));\n    }\n\n'''
s=replace_between(s,'    private void renderProductsGrid(','    private String productIcon',new_grid)

