new_product_dialog='''    private void productDialog(PosDb.Product p){\n        pendingImageUri=p==null||p.imageUri==null?"":p.imageUri;\n        LinearLayout box=col(); box.setPadding(dp(14),dp(4),dp(14),0); EditText name=input("اسم المنتج",false), category=input("التصنيف",false), price=input("السعر",true), stock=input("الكمية الحالية",true), low=input("حد انخفاض المخزون",true), barcode=input("الباركود - اختياري",false);\n        pendingImageView=new ImageView(this); pendingImageView.setScaleType(ImageView.ScaleType.CENTER_CROP); pendingImageView.setBackground(bg(PANEL2,Color.rgb(40,77,102),12));\n        if(!pendingImageUri.isEmpty()) try{pendingImageView.setImageURI(Uri.parse(pendingImageUri));}catch(Exception ignored){}\n        Button chooseImage=btn("اختيار صورة المنتج",()->{ Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT); i.addCategory(Intent.CATEGORY_OPENABLE); i.setType("image/*"); i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION); startActivityForResult(i,REQ_PRODUCT_IMAGE); });\n        if(p!=null){name.setText(p.name);category.setText(p.category);price.setText(String.format(Locale.US,"%.2f",p.priceMinor/100.0));stock.setText(String.valueOf(p.stockQty));low.setText(String.valueOf(p.lowStock));barcode.setText(p.barcode==null?"":p.barcode);} else {stock.setText("999");low.setText("5");}\n        box.addView(pendingImageView,new LinearLayout.LayoutParams(-1,dp(150))); box.addView(chooseImage,new LinearLayout.LayoutParams(-1,dp(48))); box.addView(name);box.addView(category);box.addView(price);box.addView(stock);box.addView(low);box.addView(barcode);\n        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(p==null?"إضافة منتج":"تعديل المنتج").setView(box).setPositiveButton("حفظ",null).setNegativeButton("إلغاء",null).create();\n        dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{PosDb.Product next=new PosDb.Product(p==null?null:p.id,name.getText().toString(),category.getText().toString(),parseMoney(price.getText().toString()),Integer.parseInt(stock.getText().toString()),Integer.parseInt(low.getText().toString()),barcode.getText().toString(),p==null||p.active,pendingImageUri);db.upsertProduct(next);dialog.dismiss();pendingImageView=null;showPage();}catch(Exception e){error(e.getMessage());}})); dialog.show();\n    }\n\n'''
