new_settings='''    private void settings(){\n        content.addView(title("الإعدادات","بيانات المنشأة والطابعة والنسخ الاحتياطي"),new LinearLayout.LayoutParams(-1,dp(62))); LinearLayout p=(LinearLayout)panel();\n        EditText business=input("اسم المنشأة",false), phone=input("رقم الهاتف",false), taxNo=input("الرقم الضريبي - اختياري",false), taxRate=input("نسبة الضريبة %",true); CheckBox taxEnabled=new CheckBox(this); taxEnabled.setText("المنشأة مع ضريبة"); taxEnabled.setTextColor(Color.WHITE);\n        business.setText(prefs.getString("business_name","اسم المنشأة")); phone.setText(prefs.getString("business_phone","")); taxNo.setText(prefs.getString("business_tax_no","")); taxEnabled.setChecked(prefs.getBoolean("tax_enabled",false)); taxRate.setText(String.format(Locale.US,"%.2f",prefs.getInt("tax_bps",0)/100.0));\n        p.addView(business,new LinearLayout.LayoutParams(-1,dp(50))); p.addView(phone,new LinearLayout.LayoutParams(-1,dp(50))); p.addView(taxNo,new LinearLayout.LayoutParams(-1,dp(50))); p.addView(taxEnabled,new LinearLayout.LayoutParams(-1,dp(46))); p.addView(taxRate,new LinearLayout.LayoutParams(-1,dp(50)));\n        Button saveBusiness=btn("حفظ بيانات المنشأة",()->requireOwner(()->{try{BigDecimal pct=new BigDecimal(taxRate.getText().toString().trim().isEmpty()?"0":taxRate.getText().toString().trim().replace('٫','.')); if(pct.compareTo(BigDecimal.ZERO)<0||pct.compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException("نسبة الضريبة غير صحيحة"); int bps=pct.multiply(new BigDecimal("100")).setScale(0,RoundingMode.HALF_UP).intValueExact(); prefs.edit().putString("business_name",business.getText().toString().trim()).putString("business_phone",phone.getText().toString().trim()).putString("business_tax_no",taxNo.getText().toString().trim()).putBoolean("tax_enabled",taxEnabled.isChecked()).putInt("tax_bps",bps).apply(); loadBusinessSettings(); toast("تم حفظ بيانات المنشأة"); showPage();}catch(Exception e){error(e.getMessage());}})); p.addView(saveBusiness,new LinearLayout.LayoutParams(-1,dp(50)));\n        p.addView(txt("الطابعة الأساسية: SUNMI داخلية • 80mm",14)); EditText host=input("عنوان IP للطابعة الاحتياطية",false); host.setText(prefs.getString("printer_host","192.168.100.55")); EditText port=input("منفذ الطابعة",true); port.setText(String.valueOf(prefs.getInt("printer_port",9100))); p.addView(host,new LinearLayout.LayoutParams(-1,dp(50))); p.addView(port,new LinearLayout.LayoutParams(-1,dp(50)));\n        Button savePrinter=btn("حفظ إعدادات الطابعة",()->requireOwner(()->{try{int value=Integer.parseInt(port.getText().toString()); if(value<1||value>65535)throw new IllegalArgumentException("المنفذ غير صحيح"); prefs.edit().putString("printer_host",host.getText().toString().trim()).putInt("printer_port",value).apply(); toast("تم حفظ إعدادات الطابعة");}catch(Exception e){error(e.getMessage());}})); p.addView(savePrinter,new LinearLayout.LayoutParams(-1,dp(50)));\n        Button test=btn("اختبار الطابعة",()->printRaw("ME POS Cashier\\nاختبار الطابعة\\n\\n")); p.addView(test,new LinearLayout.LayoutParams(-1,dp(50)));\n        LinearLayout backup=row(); Button export=btn("إنشاء نسخة احتياطية",this::requestBackupExport); Button restore=btn("استعادة نسخة",()->requireOwner(this::requestBackupRestore)); add(backup,export,0,dp(52),1); add(backup,restore,0,dp(52),1); p.addView(backup,new LinearLayout.LayoutParams(-1,dp(58)));\n        TextView note=txt("كل تعديل إداري حساس يتطلب صلاحية المالك. رقم المالك محفوظ على الجهاز كبصمة مشفرة وليس داخل الكود العام.",11); note.setTextColor(MUTED); p.addView(note); content.addView(p,new LinearLayout.LayoutParams(-1,-2));\n    }\n\n'''
