new_print='''    private String receipt(PosDb.Sale s){ StringBuilder out=new StringBuilder(); String business=prefs.getString("business_name","اسم المنشأة"); out.append("ME POS Cashier\\n").append(business).append("\\n"); String phone=prefs.getString("business_phone",""); String taxNo=prefs.getString("business_tax_no",""); if(!phone.isEmpty())out.append("هاتف: ").append(phone).append("\\n"); if(!taxNo.isEmpty())out.append("الرقم الضريبي: ").append(taxNo).append("\\n"); out.append(date(s.createdAt)).append("\\n------------------------------\\n"); for(PosDb.SaleItem i:db.saleItemsDetailed(s.id))out.append(i.name).append(" x").append(i.qty).append("   ").append(money(i.lineTotalMinor)).append("\\n"); out.append("------------------------------\\n"); if(s.taxMinor>0)out.append("قبل الضريبة: ").append(money(s.subtotalMinor)).append("\\nالضريبة: ").append(money(s.taxMinor)).append("\\n"); out.append("الإجمالي: ").append(money(s.totalMinor)).append("\\nالدفع: ").append(paymentName(s.payment)).append("\\nEngineer Mahmoud Ebid\\n"); return out.toString(); }\n    private String receiptBody(PosDb.Sale s){ StringBuilder b=new StringBuilder(); for(PosDb.SaleItem i:db.saleItemsDetailed(s.id))b.append(i.name).append("  ×").append(i.qty).append("   ").append(money(i.lineTotalMinor)).append("\\n"); return b.toString(); }\n    private String receiptTotals(PosDb.Sale s){ StringBuilder b=new StringBuilder(); if(s.taxMinor>0)b.append("قبل الضريبة: ").append(money(s.subtotalMinor)).append("\\nالضريبة: ").append(money(s.taxMinor)).append("\\n"); b.append("الإجمالي: ").append(money(s.totalMinor)).append("\\nالدفع: ").append(paymentName(s.payment)); return b.toString(); }\n    private void printInvoice(PosDb.Sale s){\n        String business=prefs.getString("business_name","اسم المنشأة"),phone=prefs.getString("business_phone",""),taxNo=prefs.getString("business_tax_no",""); String details=(phone.isEmpty()?"":"هاتف: "+phone+"\\n")+(taxNo.isEmpty()?"":"الرقم الضريبي: "+taxNo+"\\n");\n        String day=new SimpleDateFormat("yyyy/MM/dd",Locale.getDefault()).format(new Date(s.createdAt*1000)), tm=new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(s.createdAt*1000));\n        if(sunmi!=null && sunmi.printReceipt("ME POS Cashier",business,details,day,tm,receiptBody(s),receiptTotals(s),"Engineer Mahmoud Ebid")){ db.markPrinted(s.id); toast("تمت طباعة الفاتورة"); showPage(); return; }\n        printRaw(receipt(s),()->{db.markPrinted(s.id);toast("تمت طباعة الفاتورة");showPage();});\n    }\n    private void printRaw(String text){ printRaw(text,null); }\n    private void printRaw(String text,Runnable ok){ String host=prefs.getString("printer_host","192.168.100.55"); int port=prefs.getInt("printer_port",9100); if(sunmi!=null && sunmi.print(text)){ if(ok!=null)ok.run(); else toast("تم إرسال الطباعة إلى SUNMI"); return; } new Thread(()->{try{ThermalPrinter.print(host,port,text);runOnUiThread(()->{if(ok!=null)ok.run();else toast("تم إرسال الطباعة عبر الشبكة");});}catch(Exception e){runOnUiThread(()->error("تعذر الاتصال بالطابعة: "+e.getMessage()));}}).start(); }\n\n'''
s=s[:start]+new_print+s[end:]
main.write_text(s,encoding='utf-8')

