styled='''    public boolean printReceipt(String program,String business,String details,String date,String time,String body,String totals,String footer){\n        SunmiPrinterService s=service; if(s==null)return false;\n        try{\n            s.printerInit(null);\n            s.setAlignment(1,null);\n            s.printTextWithFont(program+"\\n",null,20f,null);\n            s.printTextWithFont(business+"\\n",null,32f,null);\n            if(details!=null&&!details.isEmpty())s.printTextWithFont(details,null,20f,null);\n            s.printColumnsString(new String[]{date,time},new int[]{1,1},new int[]{0,2},null);\n            s.printText("--------------------------------\\n",null);\n            s.setAlignment(2,null);\n            s.printText(body,null);\n            s.printText("--------------------------------\\n",null);\n            s.printTextWithFont(totals+"\\n",null,24f,null);\n            s.setAlignment(1,null);\n            s.printTextWithFont(footer+"\\n",null,20f,null);\n            s.lineWrap(2,null);\n            try{s.cutPaper(null);}catch(Exception ignored){}\n            return true;\n        }catch(RemoteException e){ service=null; return false; }\n    }\n\n'''
